#include <psp2/ctrl.h>
#include <psp2/kernel/processmgr.h>
#include <vita2d.h>
#include <algorithm>
#include <string>
#include <sys/stat.h>
#include <vector>
#include "library.h"
static const char* LIB="ux0:data/SteamVita/games";
static unsigned C(unsigned r,unsigned g,unsigned b){return RGBA8(r,g,b,255);}
static void txt(vita2d_pgf*f,float x,float y,float s,unsigned c,const std::string&t){vita2d_pgf_draw_text(f,x,y,c,s,t.c_str());}
int main(){mkdir("ux0:data/SteamVita",0777);mkdir(LIB,0777);vita2d_init();vita2d_set_vblank_wait(1);auto*f=vita2d_load_default_pgf();if(!f)return 1;sceCtrlSetSamplingMode(SCE_CTRL_MODE_ANALOG_WIDE);auto games=scan_game_library(LIB);int sel=0;unsigned prev=0;bool run=true;std::string status=games.empty()?"Add a game folder, then press Triangle.":"SteamVita v0.1 launcher prototype.";while(run){SceCtrlData p{};sceCtrlPeekBufferPositive(0,&p,1);unsigned hit=p.buttons&~prev;prev=p.buttons;if((hit&SCE_CTRL_UP)&&!games.empty())sel=(sel-1+(int)games.size())%(int)games.size();if((hit&SCE_CTRL_DOWN)&&!games.empty())sel=(sel+1)%(int)games.size();if(hit&SCE_CTRL_TRIANGLE){games=scan_game_library(LIB);sel=0;status=games.empty()?"No game folders found.":"Library rescanned.";}if((hit&SCE_CTRL_CROSS)&&!games.empty()){auto&g=games[sel];status=g.backend=="dosbox"?"DOSBox backend is our next milestone.":g.backend=="x86"?"x86 backend is experimental and not implemented yet.":"No runnable backend yet for "+g.name;}if(hit&SCE_CTRL_CIRCLE)run=false;vita2d_start_drawing();vita2d_clear_screen();vita2d_draw_rectangle(0,0,960,544,C(18,20,27));vita2d_draw_rectangle(0,0,960,72,C(29,33,43));vita2d_draw_rectangle(0,70,960,2,C(115,164,255));txt(f,28,46,1.25f,C(240,242,247),"SteamVita");txt(f,285,43,.70f,C(155,164,181),"experimental PC game launcher");vita2d_draw_rectangle(28,98,560,368,C(29,33,43));if(games.empty()){txt(f,52,148,.95f,C(240,242,247),"No games found");txt(f,52,182,.72f,C(155,164,181),"Create folders in:");txt(f,52,210,.72f,C(115,164,255),LIB);}else{int start=std::max(0,sel-6);for(int row=0;row<7&&start+row<(int)games.size();++row){int idx=start+row,y=107+row*50;if(idx==sel)vita2d_draw_rectangle(38,y,540,46,C(65,83,125));txt(f,52,y+30,.86f,C(240,242,247),games[idx].name);txt(f,418,y+30,.64f,C(155,164,181),games[idx].backend);}}vita2d_draw_rectangle(612,98,320,368,C(29,33,43));txt(f,632,134,.85f,C(115,164,255),"Selected game");if(!games.empty()){auto&g=games[sel];txt(f,632,174,.92f,C(240,242,247),g.name);txt(f,632,220,.70f,C(155,164,181),"Backend");txt(f,632,248,.78f,C(240,242,247),g.backend);txt(f,632,292,.70f,C(155,164,181),"Entry");txt(f,632,320,.70f,C(240,242,247),g.entry.empty()?"(not set)":g.entry);txt(f,632,386,.68f,C(155,164,181),"X launch");txt(f,632,414,.68f,C(155,164,181),"Triangle rescan");txt(f,632,442,.68f,C(155,164,181),"Circle exit");}vita2d_draw_rectangle(0,490,960,54,C(29,33,43));txt(f,26,524,.68f,C(155,164,181),status);vita2d_end_drawing();vita2d_swap_buffers();}vita2d_free_pgf(f);vita2d_fini();sceKernelExitProcess(0);return 0;}
